package org.sleepwell.app;

import android.app.Activity;
import android.content.SharedPreferences;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.function.Consumer;

/** Compact Settle in mix. Existing revision-checked preferences and playback remain the owners. */
final class NightDialMixerPanel extends LinearLayout {
    private final Activity activity;private final SharedPreferences preferences;private final Handler handler=new Handler(Looper.getMainLooper());
    private SoundMix mix;private long revision;private final TextView state;private final Design.Icon transport;private String issue="";
    private final Runnable tick=new Runnable(){public void run(){if(!isAttachedToWindow()||getWindowVisibility()!=VISIBLE)return;refresh();handler.postDelayed(this,1000);}};
    NightDialMixerPanel(Activity activity,Consumer<String> edit,Runnable library){super(activity);this.activity=activity;setOrientation(VERTICAL);SharedPreferences loaded=null;try{loaded=SoundPreferences.factory.open(activity);mix=SoundPreferences.load(loaded).copy();revision=SoundPreferences.revision(loaded);}catch(RuntimeException failed){mix=new SoundMix();issue="Saved mix unavailable. Open Sleep sounds to review.";}preferences=loaded;
        LinearLayout player=Design.row(activity);state=Design.text(activity,"",13,400,NightDialTokens.SECONDARY);player.addView(state,new LayoutParams(0,-2,1));transport=new Design.Icon(activity,"play",NightDialTokens.TEXT);transport.setPadding(dp(13),dp(13),dp(13),dp(13));transport.setBackground(Design.touch(activity,NightDialTokens.SECONDARY_ACTION,100));transport.setFocusable(true);transport.setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_YES);SoundEventUi.button(transport);transport.setOnClickListener(view->{InteractionFeedback.action(view);SleepSoundService.Snapshot current=SleepSoundService.snapshot();boolean playing=current!=null&&(current.state==SoundPlayback.State.PLAYING||current.state==SoundPlayback.State.LOADING);SleepSoundService.command(activity,playing?SleepSoundService.PAUSE:SleepSoundService.PLAY);handler.postDelayed(this::refresh,150);});TextView browse=Design.text(activity,"Library",13,500,NightDialTokens.SECONDARY);browse.setGravity(Gravity.CENTER);browse.setMinimumHeight(dp(48));browse.setFocusable(true);browse.setBackground(Design.touch(activity,android.graphics.Color.TRANSPARENT,12));browse.setContentDescription("Open sound library");SoundEventUi.button(browse);browse.setOnClickListener(v->{InteractionFeedback.action(v);library.run();});player.addView(browse,new LayoutParams(dp(64),dp(48)));player.addView(transport,new LayoutParams(dp(48),dp(48)));addView(player);
        if(!issue.isEmpty()){Design.item(this,"music","Review sleep sounds",null,library);refresh();return;}gain(mix.label(),mix.primaryGain,false);if(!mix.primary.equals("Brown noise")){Design.space(this,8);gain("Brown noise",mix.brownGain,true);}Design.space(this,8);
        LinearLayout choices=Design.row(activity);choice(choices,"clock","Timer",mix.timerMinutes+" min",()->edit.accept("timer"));choice(choices,"fade","Fade",mix.fadeMinutes==0?"Off":mix.fadeMinutes+" min",()->edit.accept("fade"));addView(choices);Design.space(this,4);refresh();
    }
    private void choice(LinearLayout row,String icon,String title,String value,Runnable click){LinearLayout column=Design.col(activity);Design.pad(column,12,10);column.setMinimumHeight(dp(64));column.setBackground(Design.touch(activity,NightDialTokens.SURFACE,12));LinearLayout heading=Design.row(activity);heading.addView(new Design.Icon(activity,icon,NightDialTokens.SECONDARY),new LayoutParams(dp(20),dp(20)));TextView name=Design.text(activity,title,12,400,NightDialTokens.SECONDARY);LayoutParams namePosition=new LayoutParams(0,-2,1);namePosition.leftMargin=dp(8);heading.addView(name,namePosition);column.addView(heading);Design.space(column,5);Design.text(column,value,16,500,NightDialTokens.TEXT);column.setContentDescription(title+", "+value);column.setFocusable(true);column.setScreenReaderFocusable(true);SoundEventUi.button(column);column.setOnClickListener(view->{InteractionFeedback.action(view);click.run();});LayoutParams position=new LayoutParams(0,-2,1);if(row.getChildCount()>0)position.leftMargin=dp(12);row.addView(column,position);}
    private void gain(String name,int value,boolean brown){LinearLayout labels=Design.row(activity);TextView title=Design.text(activity,name,16,500,NightDialTokens.TEXT);title.setMaxLines(2);labels.addView(title,new LayoutParams(0,-2,1));TextView percent=Design.text(activity,value+"%",14,400,NightDialTokens.SECONDARY);labels.addView(percent);addView(labels);String asset=brown?"brown.wav":switch(mix.primary){case "Rain"->"rain.wav";case "Ocean"->"ocean.wav";case "Fireplace"->"fireplace.wav";case "Wind"->"wind.wav";case "Brown noise"->"brown.wav";default->null;};NightDialWaveform waveform=new NightDialWaveform(activity,asset);waveform.gain(value,false);addView(waveform,new LayoutParams(-1,dp(40)));SeekBar slider=new SeekBar(activity);slider.setMax(100);slider.setProgress(value);slider.setContentDescription(name+" volume");SoundSliders.style(slider);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){int began;boolean dragging;public void onStartTrackingTouch(SeekBar bar){began=bar.getProgress();dragging=true;}public void onStopTrackingTouch(SeekBar bar){dragging=false;if(began!=bar.getProgress())InteractionFeedback.selection(bar);}public void onProgressChanged(SeekBar bar,int level,boolean user){if(!user)return;try{SoundMix next=mix.copy();if(brown)next.brownGain=level;else next.primaryGain=level;if(!SoundPreferences.saveIfRevision(preferences,revision,next))throw new IllegalStateException("Mix changed. Reopen Settle in before editing.");mix=next;revision=SoundPreferences.revision(preferences);percent.setText(level+"%");waveform.gain(level,true);SleepSoundService.update(activity);if(!dragging)InteractionFeedback.selection(bar);}catch(RuntimeException failed){issue="Mix could not be saved. Open Sleep sounds to review.";bar.setEnabled(false);refresh();}}});addView(slider,new LayoutParams(-1,dp(48)));}
    private void refresh(){SleepSoundService.Snapshot current=SleepSoundService.snapshot();boolean playing=current!=null&&(current.state==SoundPlayback.State.PLAYING||current.state==SoundPlayback.State.LOADING);transport.setEnabled(playing||issue.isEmpty());transport.setAlpha(transport.isEnabled()?1:.4f);transport.glyphName(playing?"pause":"play");transport.setContentDescription((playing?"Pause":"Play")+" sleep sounds");String error=SleepSoundService.error(activity);String label=!issue.isEmpty()?issue:!error.isEmpty()?error:current!=null&&current.state==SoundPlayback.State.LOADING?"Loading sounds…":playing?"Playing · "+(current.elapsed/60000)+" min / "+mix.timerMinutes+" min":current!=null&&current.state==SoundPlayback.State.PAUSED?"Paused · timer stopped":mix.withTracking?"Mix plays with a new recording":"Play sounds without starting a night";state.setText(label);state.setTextColor(!issue.isEmpty()||!error.isEmpty()?NightDialTokens.NEGATIVE:NightDialTokens.SECONDARY);}
    @Override protected void onAttachedToWindow(){super.onAttachedToWindow();handler.post(tick);}
    @Override protected void onDetachedFromWindow(){handler.removeCallbacksAndMessages(null);super.onDetachedFromWindow();}
    @Override protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);if(handler==null)return;handler.removeCallbacks(tick);if(visibility==VISIBLE&&isAttachedToWindow())handler.post(tick);}
    private int dp(int value){return Design.dp(activity,value);}
}
